using System.Security.Claims; using AeC.Application.DTOs; using AeC.Application.Interfaces; using AeC.Web.ViewModels; using Microsoft.AspNetCore.Authentication; using Microsoft.AspNetCore.Authentication.Cookies; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc;
namespace AeC.Web.Controllers;
public sealed class AccountController(IAuthService auth) : Controller
{ [AllowAnonymous] public IActionResult Login(string? returnUrl=null){ ViewBag.ReturnUrl=returnUrl; return View(new LoginViewModel()); }
 [HttpPost,AllowAnonymous,ValidateAntiForgeryToken] public async Task<IActionResult> Login(LoginViewModel vm,string? returnUrl=null){ if(!ModelState.IsValid) return View(vm); var user=await auth.AutenticarAsync(new LoginDto(vm.Usuario,vm.Senha)); if(user is null){ ModelState.AddModelError(string.Empty,"Usuário ou senha inválidos."); return View(vm);} var claims=new[]{new Claim(ClaimTypes.NameIdentifier,user.Id.ToString()),new Claim(ClaimTypes.Name,user.Nome),new Claim("Usuario",user.Usuario)}; await HttpContext.SignInAsync(CookieAuthenticationDefaults.AuthenticationScheme,new ClaimsPrincipal(new ClaimsIdentity(claims,CookieAuthenticationDefaults.AuthenticationScheme))); return LocalRedirect(string.IsNullOrWhiteSpace(returnUrl)?Url.Action("Index","Enderecos")!:returnUrl); }
 [Authorize] public async Task<IActionResult> Logout(){ await HttpContext.SignOutAsync(); return RedirectToAction(nameof(Login)); }
 [AllowAnonymous] public IActionResult Register(){ if(User.Identity?.IsAuthenticated==true) return RedirectToAction("Index","Enderecos"); return View(new RegisterViewModel()); }
 [HttpPost,AllowAnonymous,ValidateAntiForgeryToken] public async Task<IActionResult> Register(RegisterViewModel vm){ if(!ModelState.IsValid) return View(vm); var result=await auth.CadastrarAsync(new CadastroDto(vm.Nome,vm.Usuario,vm.Senha)); if(!result.Sucesso){ ModelState.AddModelError("Usuario",result.Erro!); return View(vm);} TempData["RegisterSuccess"]="Conta criada com sucesso! Faça o login para continuar."; return RedirectToAction(nameof(Login)); } }
